import{z as s,x as n,o as A,c as d,q as i,j as t,D as a,d as e,s as r,S as o,b as B}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"步数蒸馏的服务权衡","description":"","frontmatter":{"title":"步数蒸馏的服务权衡","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/diff-step-distill-tradeoff.md","filePath":"llm/diff-step-distill-tradeoff.md","lastUpdated":1791413859000}'),p={name:"llm/diff-step-distill-tradeoff.md"};function m(D,E,f,F,C,h){const l=n("Mermaid");return A(),d("div",null,[E[2]||(E[2]=i('<h1 id="步数蒸馏的服务权衡" tabindex="-1">步数蒸馏的服务权衡 <a class="header-anchor" href="#步数蒸馏的服务权衡" aria-label="Permalink to &quot;步数蒸馏的服务权衡&quot;">​</a></h1><div class="epigraph"><p>蒸馏把步数从「质量税」变成「服务契约」：步数一旦蒸进权重，就不再是用户可以在请求里随便改的参数。</p><footer>—— 据 Salimans &amp; Ho 渐进蒸馏、Luo 等 LCM 与少步扩散的服务实践整理</footer></div><p><a href="/llm/diff-serving-pipeline">上一课</a>把管线切成一次性段、循环段与收尾段，并把成本约化成「少跑前向」与「跑便宜前向」两条。本课动第一条：步数蒸馏。蒸馏的方法谱系——渐进蒸馏、一致性模型、分布匹配——在<a href="/llm/diffusion-distillation">扩散蒸馏与少步</a>已立；本课只算服务视角的账：换来什么，赔上什么，哪些旋钮随之消失。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>教师的默认配置是 25 到 50 步加 CFG 双前向，一次请求一百次量级的前向；交互式场景（边拖边看的预览）在单卡上排不进延迟预算。蒸馏学生把步数压到 4 到 8 步，且常把引导蒸进权重，单前向即可出图。账面收益清楚：\\(100\\) 次前向变 \\(4\\) 次，二十多倍。缺口在另一半：学生赔掉了什么，往往不在发布时的 FID 里，而在用户的具体请求里——细节变平、贴合下降，以及最容易被忽略的：\\(\\gamma\\) 旋钮没了。把学生当「更快的教师」用，会在生产里踩进这些静默的坑。</p><h3 id="消失的旋钮" tabindex="-1">消失的旋钮 <a class="header-anchor" href="#消失的旋钮" aria-label="Permalink to &quot;消失的旋钮&quot;">​</a></h3><p>教师管线里 \\(\\gamma\\) 是按请求可调的旋钮：写实的调低、贴合的调高。引导蒸进学生后，CFG 分支消失，\\(\\gamma\\) 不再存在；要不同的「引导手感」，只能换一个蒸法或换一个学生。同时步数也进了契约：学生在自己规定的 4 到 8 步日程上训练，多跑或少跑、换用教师日程的采样器配置，都会静默劣化而不是报错。API 层必须把参数收走或锁死，否则用户会拿教师的用法打学生。</p><p><span class="marginnote">教师 50 步 × 双前向 = 100 次前向；引导蒸馏学生 4 步 × 单前向 = 4 次，二十余倍的差距里有一半来自 CFG 分支消失而不是步数本身——评估蒸馏收益要把两笔账分开报。</span></p><p><span class="marginnote">把 CFG 的 \\(\\gamma\\) 想成「听话程度旋钮」：调高，模型更死贴提示词的字面，颜色和构图容易过饱和；调低，画面更自然但可能跑题。它本来是每个请求各调各的；一旦蒸进权重，相当于把这个旋钮焊死在出厂档位上，所有请求共享同一个手感。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按流量分层配模型，而不是全员换学生：</p><ul><li><strong>交互层</strong>：预览、变体瀑布流、参数探索用少步学生；延迟是第一 SLO，质量下限即可。</li><li><strong>成图层</strong>：最终出图保留教师或「学生打底 + 教师精修几步」的混合管线；蒸馏损失集中在高频细节，精修步数远少于全程。</li><li><strong>LoRA 形态</strong>：LCM-LoRA 一类把蒸馏挂在适配器上，同一底座按请求挂载或摘除，学生与教师共存一张卡，按流量切——省多份全模型的显存，代价是每请求多一次切换合并。</li></ul><p><span class="marginnote">直觉类比：LoRA 形态就像给同一台相机外挂不同滤镜——机身（底座权重）始终只有一份，「蒸馏补丁」是小巧的滤镜片，接到请求时几分钟装上、不用时摘下。省的是「为每个学生复制一台相机」的显存，付的是每次装卸滤镜的小延迟。</span></p><p>上线前必须单独报步数–质量：学生在 4 步的 FID 不能抄教师 50 步的数，也不能混用参考统计。调度器配置与蒸馏契约绑定存档：采样器、时间步间距、CFG 开关一起进版本号。</p>',14)),(A(),t(o,null,{default:a(()=>[r(l,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%E8%BF%9B%E6%9D%A5%22%5D%20--%3E%20TIER%7B%22%E6%B5%81%E9%87%8F%E5%88%86%E5%B1%82%22%7D%0A%20%20TIER%20--%3E%7C%E4%BA%A4%E4%BA%92%E9%A2%84%E8%A7%88%7C%20STU%5B%22%E5%B0%91%E6%AD%A5%E5%AD%A6%E7%94%9F%EF%BC%9A4-8%20%E6%AD%A5%E5%8D%95%E5%89%8D%E5%90%91%22%5D%0A%20%20TIER%20--%3E%7C%E6%9C%80%E7%BB%88%E6%88%90%E5%9B%BE%7C%20MIX%5B%22%E5%AD%A6%E7%94%9F%E6%89%93%E5%BA%95%20%2B%20%E6%95%99%E5%B8%88%E7%B2%BE%E4%BF%AE%22%5D%0A%20%20TIER%20--%3E%7C%E6%95%8F%E6%84%9F%E7%BB%86%E8%8A%82%7C%20TEA%5B%22%E6%95%99%E5%B8%88%20%2B%20CFG%22%5D%0A%20%20STU%20--%3E%20Q%7B%22%E8%B4%A8%E9%87%8F%E5%A4%9F%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%E5%90%A6%7C%20MIX%0A%20%20MIX%20--%3E%20SHIP%5B%22%E5%87%BA%E5%9B%BE%22%5D%0A%20%20TEA%20--%3E%20SHIP%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[e("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"为什么蒸馏能砍步数而直接减步不行：教师日程的末端信噪比设计假定每步做小幅修正，跳步会让误差来不及被剩余步校正；蒸馏把多步修正的复合映射压进单步，学生学的是「跳到的终点」而不是「下一步」。为什么学生会继承教师的毛病：分布匹配只对齐分布、一致性只自洽于轨迹，教师带引导放大的伪影与模式会原样进学生——所以换教师版本等于换学生，回归测试要成对跑。",-1)),(A(),t(o,null,{default:a(()=>[r(l,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20T%5B%22%E6%95%99%E5%B8%88%EF%BC%9A50%20%E6%AC%A1%E5%B0%8F%E5%B9%85%E4%BF%AE%E6%AD%A3%22%5D%0A%20%20%20%20T1%5B%22%E7%BA%AF%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20T2%5B%22%E7%AC%AC%201%20%E6%AD%A5%EF%BC%9A%E5%BE%AE%E8%B0%83%22%5D%0A%20%20%20%20T2%20--%3E%20T3%5B%22%E7%AC%AC%202%20%E6%AD%A5%EF%BC%9A%E5%BE%AE%E8%B0%83%22%5D%0A%20%20%20%20T3%20--%3E%20T4%5B%22%E2%80%A6%E2%80%A6%E9%80%90%E6%AD%A5%E9%80%BC%E8%BF%91%22%5D%0A%20%20%20%20T4%20--%3E%20T5%5B%22%E5%B9%B2%E5%87%80%E5%9B%BE%22%5D%0A%20%20end%0A%20%20subgraph%20S%5B%22%E7%9B%B4%E6%8E%A5%E8%B7%B3%E6%AD%A5%EF%BC%9A%E8%AF%AF%E5%B7%AE%E6%B2%A1%E4%BA%BA%E6%93%A6%22%5D%0A%20%20%20%20S1%5B%22%E7%BA%AF%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20S2%5B%22%E8%B7%B3%E8%BF%87%E4%B8%AD%E9%97%B4%E6%AD%A5%22%5D%0A%20%20%20%20S2%20--%3E%20S3%5B%22%E8%AF%AF%E5%B7%AE%E8%B6%8A%E7%A7%AF%E8%B6%8A%E5%A4%A7%22%5D%0A%20%20%20%20S3%20--%3E%20S4%5B%22%E5%8A%A3%E5%8C%96%E5%9B%BE%22%5D%0A%20%20end%0A%20%20subgraph%20D%5B%22%E8%92%B8%E9%A6%8F%E5%AD%A6%E7%94%9F%EF%BC%9A%E5%AD%A6%E4%BC%9A%E5%A4%A7%E8%B7%B3%22%5D%0A%20%20%20%20D1%5B%22%E7%BA%AF%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20D2%5B%22%E5%8D%95%E6%AD%A5%E7%9B%B4%E6%8E%A5%E9%A2%84%E6%B5%8B%E7%BB%88%E7%82%B9%22%5D%0A%20%20%20%20D2%20--%3E%20D3%5B%22%E5%8F%AF%E7%94%A8%E7%9A%84%E5%B0%91%E6%AD%A5%E5%9B%BE%22%5D%0A%20%20end%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=i('<p>为什么交互层先受益：预览的价值在「反馈回路短」，用户看到大概构图就能改提示词；质量瑕疵在探索阶段成本低。成图层则相反，用户对最后一张的高频结构最敏感，恰好是蒸馏最先丢的部分。把两层分开，蒸馏的收益就落在不伤害付费质量的地方。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>蒸馏不是免费吞吐：学生改变误差的频谱分布，只看整体 FID 会漏掉局部细节退化，需配对人评抽检——本课程后面的评测课给管线。蒸馏与量化会互相放大（<a href="/llm/diff-quantization">下一课</a>），上线前要联合验证而不是各自达标。</p><p><span class="marginnote">「互相放大」是什么意思：蒸馏丢掉的细节和量化抹平的精度往往伤在同一批高频纹理上。学生单独测 FID 达标、量化模型单独测也达标，两个叠加后细节损失不是相加而是相乘——所以验收必须用「蒸完再量化」的最终形态一起跑，而不是两关各过各的。</span>引导被蒸死后，「按请求调 \\(\\gamma\\)」的产品能力随之消失，文档与 API 参数要同步收口；保留 \\(\\gamma\\) 需求的场景应选未蒸引导的学生并接受双前向。最后，蒸馏契约与底座版本强耦合：换底座重蒸，历史用户的同参数复现即被打破，版本谱系要提前设计。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>蒸馏把步数压一个量级，收益一半来自砍 CFG 分支，账要分开报。</li><li>学生把步数与日程变成模型契约：采样器配置必须绑定存档，不能沿用教师。</li><li>引导蒸进权重则 \\(\\gamma\\) 旋钮消失，API 要收参数而不是留一个失效的旋钮。</li><li>按流量分层：交互用学生、成图用混合或教师，LoRA 形态让两者共存一卡。</li><li>学生继承教师的伪影与模式，换教师版本须成对回归。</li><li>出处：Salimans &amp; Ho 渐进蒸馏、Song 等一致性模型、Luo 等 LCM；服务口径据本课整理。</li></ul>',6))])}const g=s(p,[["render",m]]);export{T as __pageData,g as default};
